// Everyone who has signed in, by lower-cased name, with the name they last signed in with.
export type UserDirectory = Map<string, string>

export const createUserDirectory = (): UserDirectory => new Map()

export const ADMIN = 'admin'

export const isAdmin = (session: { user: string }) => session.user.trim().toLowerCase() === ADMIN
import { contract, ui } from '@hozu/core'
import { admin, deleteAccount, login } from '../../routes.ts'
import { accountMachine, DeleteAccount, me, removeAccount, SignIn, SignOut, signIn, signOut } from './model.ts'
import { text } from './text.ts'

export const Login = ui.view({
  machine: accountMachine,
  route: login,
  render: ({ ctx, search, locale }) =>
    ui.main({ class: 'mx-auto max-w-sm space-y-6 px-4 py-16' }, [
      ui.h1({ class: 'text-3xl font-bold' }, [text.signIn]),
      ui.a({ href: locale === 'en' ? ui.alternate('de') : ui.alternate('en'), class: 'text-sm underline' }, [text.language]),
      search.deleted && ui.p({ role: 'status', class: 'rounded border bg-slate-50 px-4 py-2 text-sm' }, [text.accountDeleted]),
      ui.form({ class: 'space-y-3', on: { submit: ui.send(SignIn, { name: ui.dom.form('name') }) } }, [
        ui.label({ for: 'name', class: 'block text-sm font-medium' }, [text.name]),
        ui.input({
          id: 'name',
          name: 'name',
          required: true,
          minlength: 2,
          maxlength: 20,
          pattern: '[A-Za-z]{2,20}',
          autocomplete: 'username',
          'aria-invalid': ctx.fields.name !== null,
          'aria-describedby': 'name-error',
          class: 'w-full rounded border px-3 py-2',
        }),
        ui.p({ id: 'name-error', class: 'text-sm text-rose-600' }, [ctx.fields.name]),
        ui.button({ type: 'submit', class: 'w-full rounded bg-indigo-600 px-4 py-2 text-white' }, [text.signIn]),
      ]),
      ctx.error !== null && ui.p({ role: 'alert', class: 'text-rose-600' }, [ctx.error]),
    ]),
